document.addEventListener('visibilitychange',()=>{if(document.hidden&&recording){cancelRecording();toast('أوقفنا الحفظ لأن التطبيق انتقل إلى الخلفية.')}});
function installHelp(){sheet('Lumora على شاشتك الرئيسية',`<p>افتح هذا الرابط في <strong>Safari</strong> على الآيفون، ثم:</p><ol><li>اضغط زر <strong>المشاركة</strong> ${icon('install')} في شريط Safari.</li><li>اختر <strong>إضافة إلى الشاشة الرئيسية</strong>.</li><li>فعّل <strong>فتح كتطبيق ويب</strong> إن ظهر، ثم اضغط <strong>إضافة</strong>.</li></ol><p class="small">يُفتح Lumora بعدها بأيقونته الخاصة. أول فتح يحتاج اتصالًا؛ تُحفظ الواجهة للعمل دون اتصال بعد تجهيزها. افتح العزل مرة عبر الإنترنت لتخزين مكوّنه محليًا أيضًا.</p><p class="small">الرابط خاص بحسابك على Sites؛ قد تحتاج تسجيل الدخول بنفس حساب ChatGPT في Safari.</p>`)}
function help(){sheet('دليل لومورا',`<p><strong>Lumora للآيفون · الإصدار 1.0</strong><br>استوديو خفيف للصور والفيديو، يعمل على جهازك.</p><h3>ابدأ من لقطة</h3><p>أضف صورة أو فيديو من مكتبتك، ثم عدّل الضوء واللون أو جرّب أحد 2000 فلتر. اختيار الفلتر يعاينه أولًا؛ اضغط تطبيق للاحتفاظ به.</p><h3>الخلفية والبورتريه</h3><p>اختر العزل التلقائي، ثم حرّك العنصر أو كبّره بالمقابض وبإصبعين. ستجد 26 خلفية جاهزة. نموذج الهاتف أخف من الكمبيوتر؛ دقة الشعر والحدود تعتمد على الصورة.</p><h3>القص والأقنعة</h3><p>اسحب الإطار أو مقابضه، ثم ثبّت القص. توجد فرشاة وتدرّج شعاعي لتحديد موضعي واحد قابل للتحريك.</p><h3>الصور والفيديو</h3><p>حفظ الصور حتى 12MP حسب اختيارك وحدود الذاكرة. الفيديو يُحفظ بالمدة الفعلية حتى 1080 و30fps ولمقاطع حتى دقيقتين، بالصوت. MP4 على Safari أو الصيغة المدعومة في المتصفح. أبقِ الشاشة مفتوحة أثناء التصدير.</p><h3>العمل دون اتصال</h3><p>بعد أول فتح ناجح تُخزّن ملفات الواجهة. مكوّن العزل ينزّل نحو 20MB عند أول استخدام ويُخزّن عند توفر المساحة. متصفحك قد يحذف التخزين؛ احتفظ بالأصول وصدّر ما يهمّك.</p><p class="small">نسخة ويب وليست نسخة iOS أصلية. RAW وHDR وXMP غير مدمجة. ملف البريسيت المحمول .lumoralook مستقل عن حزمة .lumorapreset الخاصة ببرنامج الكمبيوتر.</p><p><a href="/licenses/ASSETS.md" target="_blank" rel="noopener">أصول الصور والتراخيص</a></p>`)}
function privacy(){sheet('صورك على جهازك',`<p>تُقرأ الصور والفيديو من جهازك وتُعالج داخل المتصفح. لا نرسلها إلى خادم لتحريرها أو عزلها.</p><p>تُحفظ المكتبة والتعديلات في تخزين المتصفح المحلي. حذف ملف من مكتبة لومورا لا يحذف الأصل من تطبيق الصور.</p><p>قد تزول البيانات المحلية عند مسح بيانات Safari أو نقص مساحة الجهاز؛ هذه ليست نسخة سحابية. احفظ النتائج المهمة في الصور أو الملفات.</p><p class="small">الموقع الخاص يستخدم تسجيل دخول Sites للوصول إلى الواجهة. هذا منفصل عن معالجة صورك المحلية.</p>`)}
$('#install').onclick=installHelp;$('#helpNav').onclick=help;$('#privacy').onclick=privacy;$('#homeNav').onclick=()=>guard(goHome);$('#videoNav').onclick=()=>{$('#fileInput').accept='video/*';$('#fileInput').click()};$('#looksNav').onclick=()=>guard(async()=>{if(!current){await loadSample('landscape')}tool='presets';renderTools();renderPanel()});
for(let id of ['importMain','importSmall'])$('#'+id).onclick=()=>{$('#fileInput').accept='image/*,video/*';$('#fileInput').click()};$$('[data-sample]').forEach(b=>b.onclick=()=>guard(()=>loadSample(b.dataset.sample)));$('#fileInput').onchange=()=>guard(async()=>{const files=[...$('#fileInput').files];$('#fileInput').value='';await importFiles(files)});$('#back').onclick=()=>guard(goHome);$('#undo').onclick=()=>guard(()=>step(-1));$('#redo').onclick=()=>guard(()=>step(1));$('#save').onclick=()=>guard(()=>exportSheet());$('#compare').onclick=()=>{cancelFilter();before=!before;$('#compare').classList.toggle('selected',before);renderer.setLut(before?neutralLut:lastLut);requestDraw()};$('#reset').onclick=()=>guard(async()=>{if(!confirm('إعادة كل تعديلات هذا الملف؟ الأصل محفوظ.'))return;recipe=fresh();presetBase=null;selectedPreset=null;previewRecipe=null;renderLocalMask();renderPanel();changed();await flushSave()});
$('#backgroundInput').onchange=()=>guard(async()=>{const file=$('#backgroundInput').files[0];$('#backgroundInput').value='';if(!file||!current)return;const id=current.id;let decoded=await imageFrom(file,1800);await ensureMask();if(current?.id!==id)return;current.backgroundBlob=file;recipe.background={type:'image',id:'custom'};recipe.cutout=true;backgroundSource=decoded.image;renderer.setBackground(backgroundSource);changed({color:false});renderPanel()});
function validLook(p){const finite=(v,min,max)=>typeof v==='number'&&Number.isFinite(v)&&v>=min&&v<=max;if(!p||!p.values||typeof p.values!=='object'||Object.values(p.values).some(v=>!finite(v,-1000,1000)))return false;if(!p.curves||!['rgb','r','g','b'].every(k=>{const a=p.curves[k];if(!Array.isArray(a)||a.length<2||a.length>64)return false;let last=-1;return a.every(p=>{const x=Array.isArray(p)?p[0]:p?.x,y=Array.isArray(p)?p[1]:p?.y;if(!finite(x,0,1)||!finite(y,0,1)||x<=last)return false;last=x;return true})}))return false;if(!Array.isArray(p.hsl)||p.hsl.length!==8||!p.hsl.every(a=>a&&['h','s','l'].every(k=>finite(a[k],-100,100))))return false;return p.grading&&['shadows','midtones','highlights','global'].every(k=>{let a=p.grading[k];return a&&finite(a.h,0,360)&&finite(a.s,0,100)&&finite(a.l,-100,100)})}
$('#presetInput').onchange=()=>guard(async()=>{const file=$('#presetInput').files[0];$('#presetInput').value='';if(!file)return;if(file.size>200000)throw Error('ملف البريسيت كبير أو غير متوافق.');const data=JSON.parse(await file.text());if(data.format!=='lumora-mobile-look'||data.version!==1||!validLook(data.recipe))throw Error('هذا الملف ليس بريسيت Lumora المحمول.');const p={id:crypto.randomUUID(),name:String(data.name||'My Look').slice(0,80),category:'فلاتري',recipe:data.recipe};let list=JSON.parse(localStorage.getItem('lumora-presets')||'[]');list.push(p);localStorage.setItem('lumora-presets',JSON.stringify(list));activeCategory='فلاتري';tool='presets';renderTools();renderPanel();toast('أضفنا البريسيت.')});
window.addEventListener('beforeunload',()=>{if(current){current.recipe=copy(recipe);saveMedia(current).catch(()=>{})}});window.addEventListener('pagehide',()=>{if(recording)cancelRecording()});
async function start(){try{library=(await listMedia()).sort((a,b)=>b.added-a.added)}catch{toast('التخزين المحلي غير متاح؛ يمكنك التعديل والتصدير في هذه الجلسة.')}renderLibrary();if('serviceWorker'in navigator)try{await navigator.serviceWorker.register('/sw.js',{scope:'/'});}catch{}setTimeout(()=>$('#splash')?.remove(),1100)}start();
